                        r, c = c, -r
                    pts.append((r, c))
                mr = min(r for r, c in pts)
                mc = min(c for r, c in pts)
                variants.append(tuple(sorted((r - mr, c - mc)
                                             for r, c in pts)))
            return min(variants)

        groups = {}
        for pi, (start, end) in enumerate(panels):
            points = {(r - start, c)
                      for r in range(start, end)
                      for c in range(w) if grid[r][c] == fg}
            unseen = set(points)
            while unseen:
                seed = unseen.pop()
                comp = {seed}
                stack = [seed]
                while stack:
                    r, c = stack.pop()
                    for rr in range(r - 1, r + 2):
                        for cc in range(c - 1, c + 2):
                            q = (rr, cc)
                            if q in unseen:
                                unseen.remove(q)
                                comp.add(q)
                                stack.append(q)
                if len(comp) == 3:
                    groups.setdefault(canonical(comp), []).append((pi, comp))

        repeated = [
            copies for copies in groups.values()
            if len({pi for pi, _ in copies}) > 1
        ]
        out = blank(8, w)
        if repeated:
            _, comp = max(
                (copy for group in repeated for copy in group),
                key=lambda copy: copy[0]
            )
            min_r = min(r for r, c in comp)
            for r, c in comp:
                out[r - min_r][w - 1 - c] = fg
        return out

    return [row[:] for row in grid]
